//! `cargo xtask docs-inventory`: regenerate `docs/generated/` deterministically
//! (a CON-9 gate step; TRC-20 and LOOP-30 extend it later). `--check` fails
//! when the committed files differ from what would be generated.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use serde::Serialize;

use crate::model::Model;
use crate::specs::Level;
use crate::workspace::{read, write};
use crate::{Error, Result};

/// Directory (relative to the root) that this task owns.
pub const GENERATED_DIR: &str = "docs/generated";

const HEADER: &str =
    "<!-- Generated by `cargo xtask docs-inventory`. Do not edit; regenerate. -->\n\n";

/// The JSON object `docs-inventory` prints (CON-8).
#[derive(Debug, Serialize)]
pub struct Report {
    pub ok: bool,
    pub mode: &'static str,
    pub written: Vec<String>,
    pub changed: Vec<String>,
    pub stale: Vec<String>,
}

fn md_escape(s: &str) -> String {
    s.replace('|', "\\|")
}

fn requirements_md(model: &Model) -> String {
    let by_id = model.citations_by_id();
    let mut s = String::from(HEADER);
    s.push_str("# Requirement inventory\n\n");
    let _ = writeln!(
        s,
        "Specs: {} · IDs: {} · MUSTs: {} · implemented: {} · cited: {}\n",
        model.spec_count,
        model.requirements.len(),
        model
            .requirements
            .iter()
            .filter(|r| r.level == Level::Must)
            .count(),
        model.implemented.len(),
        by_id.len()
    );
    s.push_str("| ID | Spec | § | Level | Implemented | Cited by |\n|---|---|---|---|---|---|\n");
    for r in &model.requirements {
        let level = match r.level {
            Level::Must => "MUST",
            Level::Should => "SHOULD",
            Level::May => "MAY",
            Level::None => "—",
        };
        let implemented = if model.implemented.contains(&r.id) {
            "yes"
        } else {
            "no"
        };
        let cited = by_id
            .get(r.id.as_str())
            .map(|cs| {
                cs.iter()
                    .map(|c| {
                        format!(
                            "`{}` {}",
                            c.file,
                            c.function
                                .as_deref()
                                .map(|f| format!("`{f}`"))
                                .unwrap_or_default()
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("<br>")
            })
            .unwrap_or_else(|| "—".to_owned());
        let _ = writeln!(
            s,
            "| {} | `{}` | {} | {} | {} | {} |",
            r.id,
            r.file,
            r.section.as_deref().unwrap_or("—"),
            level,
            implemented,
            md_escape(&cited)
        );
    }
    s
}

fn field<'a>(text: &'a str, key: &str) -> Option<&'a str> {
    let start = text.find(key)? + key.len();
    let rest = text[start..].lines().next().unwrap_or("");
    let end = rest.find("**").unwrap_or(rest.len());
    Some(rest[..end].trim().trim_end_matches('.'))
}

fn decisions_md(root: &Path) -> Result<String> {
    let dir = root.join("docs/decisions");
    let mut rows = Vec::new();
    if dir.is_dir() {
        let mut names: Vec<String> = std::fs::read_dir(&dir)
            .map_err(|e| Error::io(&dir, e))?
            .filter_map(std::result::Result::ok)
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.starts_with("ADR-") && n.ends_with(".md"))
            .collect();
        names.sort_by_key(|n| {
            n.trim_start_matches("ADR-")
                .trim_end_matches(".md")
                .parse::<u32>()
                .unwrap_or(u32::MAX)
        });
        for name in names {
            let text = read(&dir.join(&name))?;
            let title = text
                .lines()
                .find_map(|l| l.strip_prefix("# "))
                .unwrap_or("")
                .split_once('—')
                .map_or_else(
                    || name.trim_end_matches(".md").to_owned(),
                    |(_, t)| t.trim().to_owned(),
                );
            let status = field(&text, "**Status:**").unwrap_or("—").to_owned();
            let ids = field(&text, "**IDs affected:**").unwrap_or("—").to_owned();
            rows.push(format!(
                "| [{}](../decisions/{name}) | {} | {} | {} |",
                name.trim_end_matches(".md"),
                md_escape(&title),
                md_escape(&status),
                md_escape(&ids)
            ));
        }
    }
    let mut s = String::from(HEADER);
    s.push_str(
        "# Decision records\n\n| ADR | Title | Status | IDs affected |\n|---|---|---|---|\n",
    );
    for r in rows {
        s.push_str(&r);
        s.push('\n');
    }
    Ok(s)
}

fn lab_notes_md(root: &Path) -> Result<String> {
    let dir = root.join("docs/lab");
    let mut rows = Vec::new();
    if dir.is_dir() {
        let mut names: Vec<String> = std::fs::read_dir(&dir)
            .map_err(|e| Error::io(&dir, e))?
            .filter_map(std::result::Result::ok)
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.ends_with(".md"))
            .collect();
        names.sort();
        for name in names {
            let text = read(&dir.join(&name))?;
            let title = text
                .lines()
                .find_map(|l| l.strip_prefix("# "))
                .unwrap_or("")
                .trim();
            rows.push(format!(
                "| [{}](../lab/{name}) | {} |",
                name.trim_end_matches(".md"),
                md_escape(title)
            ));
        }
    }
    let mut s = String::from(HEADER);
    s.push_str("# Lab notes (CON-23)\n\n| Note | Title |\n|---|---|\n");
    if rows.is_empty() {
        s.push_str("| — | no lab notes yet |\n");
    }
    for r in rows {
        s.push_str(&r);
        s.push('\n');
    }
    Ok(s)
}

/// Generate every file, keyed by path relative to the root.
pub fn generate(root: &Path) -> Result<BTreeMap<String, String>> {
    let model = Model::load(root)?;
    let mut files = BTreeMap::new();
    files.insert(
        format!("{GENERATED_DIR}/requirements.md"),
        requirements_md(&model),
    );
    files.insert(format!("{GENERATED_DIR}/decisions.md"), decisions_md(root)?);
    files.insert(format!("{GENERATED_DIR}/lab-notes.md"), lab_notes_md(root)?);
    Ok(files)
}

fn stale_files(root: &Path, generated: &BTreeMap<String, String>) -> Result<Vec<String>> {
    let dir = root.join(GENERATED_DIR);
    let mut stale = Vec::new();
    if dir.is_dir() {
        for entry in std::fs::read_dir(&dir).map_err(|e| Error::io(&dir, e))? {
            let entry = entry.map_err(|e| Error::io(&dir, e))?;
            let name = entry.file_name().to_string_lossy().into_owned();
            if name.starts_with('.') {
                continue;
            }
            let key = format!("{GENERATED_DIR}/{name}");
            if !generated.contains_key(&key) {
                stale.push(key);
            }
        }
    }
    stale.sort();
    Ok(stale)
}

/// Write (or, with `check`, compare) the generated files.
pub fn run(root: &Path, check: bool) -> Result<Report> {
    let generated = generate(root)?;
    let stale = stale_files(root, &generated)?;
    let mut written = Vec::new();
    let mut changed = Vec::new();
    for (path, content) in &generated {
        let on_disk = read(&root.join(path)).ok();
        if on_disk.as_deref() != Some(content.as_str()) {
            changed.push(path.clone());
            if !check {
                write(&root.join(path), content)?;
                written.push(path.clone());
            }
        }
    }
    for c in &changed {
        tracing::warn!(file = %c, "generated documentation is out of date");
    }
    let ok = if check {
        changed.is_empty() && stale.is_empty()
    } else {
        true
    };
    Ok(Report {
        ok,
        mode: if check { "check" } else { "write" },
        written,
        changed,
        stale,
    })
}
